// TopShopsChart renders a horizontal bar chart of the top N shops by revenue.
// Uses recharts. Props:
//   data    — [{ shop_name, revenue }] sorted desc by revenue
//   loading — boolean

import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, Cell } from "recharts";

const BAR_COLOR = "#378ADD"; // blue-400

function CustomTooltip({ active, payload }) {
  if (!active || !payload?.length) return null;
  const d = payload[0].payload;
  return (
    <div style={{
      background: "var(--color-background-primary)",
      border: "0.5px solid var(--color-border-secondary)",
      borderRadius: "var(--border-radius-md)",
      padding: "8px 12px",
      fontSize: 13,
    }}>
      <p style={{ margin: "0 0 4px", fontWeight: 500 }}>{d.shop_name}</p>
      <p style={{ margin: 0, color: "var(--color-text-secondary)" }}>
        ₹{Number(d.revenue).toLocaleString("en-IN", { minimumFractionDigits: 2 })}
      </p>
    </div>
  );
}

export default function TopShopsChart({ data = [], loading = false }) {
  if (loading) {
    return (
      <div style={{ border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "1.5rem" }}>
        <div style={{ height: 14, width: 140, background: "var(--color-border-tertiary)", borderRadius: 4, marginBottom: 16 }} />
        {Array.from({ length: 5 }).map((_, i) => (
          <div key={i} style={{ display: "flex", gap: 10, marginBottom: 10, alignItems: "center" }}>
            <div style={{ height: 12, width: 100, background: "var(--color-border-tertiary)", borderRadius: 4 }} />
            <div style={{ height: 20, width: `${(5 - i) * 15}%`, background: "var(--color-border-tertiary)", borderRadius: 4 }} />
          </div>
        ))}
      </div>
    );
  }

  const chartData = data.slice(0, 10).map((d) => ({
    ...d,
    shortName: d.shop_name.length > 22 ? d.shop_name.slice(0, 22) + "…" : d.shop_name,
  }));

  return (
    <div style={{ border: "0.5px solid var(--color-border-tertiary)", borderRadius: "var(--border-radius-lg)", padding: "1.25rem 1.5rem" }}>
      <p style={{ margin: "0 0 1rem", fontWeight: 500, fontSize: 14 }}>Top shops by revenue</p>
      {chartData.length === 0 ? (
        <p style={{ textAlign: "center", color: "var(--color-text-tertiary)", padding: "2rem 0", margin: 0 }}>No data</p>
      ) : (
        <ResponsiveContainer width="100%" height={chartData.length * 36 + 20}>
          <BarChart
            data={chartData}
            layout="vertical"
            margin={{ top: 0, right: 16, left: 0, bottom: 0 }}
          >
            <XAxis
              type="number"
              tick={{ fontSize: 11, fill: "var(--color-text-tertiary)" }}
              tickFormatter={(v) => `₹${(v / 1000).toFixed(0)}k`}
              axisLine={false}
              tickLine={false}
            />
            <YAxis
              type="category"
              dataKey="shortName"
              width={140}
              tick={{ fontSize: 12, fill: "var(--color-text-secondary)" }}
              axisLine={false}
              tickLine={false}
            />
            <Tooltip content={<CustomTooltip />} cursor={{ fill: "var(--color-background-secondary)" }} />
            <Bar dataKey="revenue" radius={[0, 4, 4, 0]} barSize={18}>
              {chartData.map((_, i) => (
                <Cell key={i} fill={BAR_COLOR} fillOpacity={1 - i * 0.06} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      )}
    </div>
  );
}
